pub enum ChromaSubsampling {
    /// One luma plane and no chroma planes (AV1 `I400`, HEVC 4:0:0).
    Mono,
    /// Equal horizontal and vertical resolution.
    Yuv444,
    /// Half horizontal resolution, rounded up at an odd edge.
    Yuv422,
    /// Half horizontal and vertical resolution, rounded up at odd edges.
    Yuv420,
}

pub enum ChromaSiting {
    /// The source did not establish a location.
    #[default]
    Unknown,
    /// Centered horizontally and vertically in the subsampled luma cell
    /// (JPEG style).
    Center,
    /// Horizontally co-sited with the left luma sample, vertically centered
    /// between rows (MPEG-2 style 4:2:0).
    Left,
    /// Co-sited with the top-left luma sample.
    TopLeft,
}

impl<'a> CodePlane<'a> {
    pub fn from_u8(
        words: &'a [u8],
        width: usize,
        height: usize,
        stride_bytes: usize,
        encoding: SampleEncoding,
    ) -> Result<Self, CodePlaneError>;

    pub fn from_u16(
        words: &'a [u16],
        width: usize,
        height: usize,
        stride_bytes: usize,
        encoding: SampleEncoding,
    ) -> Result<Self, CodePlaneError>;

    pub const fn width(self) -> usize;

    pub const fn height(self) -> usize;

    pub const fn encoding(self) -> SampleEncoding;

    pub fn code(self, x: usize, y: usize) -> Option<u16>;
}

impl<'a> YcbcrToRgbF32<'a> {
    pub fn new(
        planes: [CodePlane<'a>; 3],
        sub: ChromaSubsampling,
        siting: ChromaSiting,
        color: Cicp,
    ) -> Result<Self, At<YcbcrError>>;

    pub const fn output_descriptor(&self) -> PixelDescriptor;

    pub fn convert_rows<'b>(
        &self,
        x: usize,
        y: usize,
        mut destination: PixelSliceMut<'b>,
    ) -> Result<PixelSliceMut<'b>, At<YcbcrError>>;
}

pub enum YcbcrError {
    /// Primaries, transfer or matrix is outside the implemented route.
    UnsupportedColor { actual: Cicp },
    /// Bit depth or per-plane sample encodings disagree or are unsupported.
    UnsupportedEncoding {
        plane: usize,
        actual: SampleEncoding,
    },
    /// Chroma sampling/location has no qualified kernel. Unknown is not Center.
    UnsupportedChroma {
        subsampling: ChromaSubsampling,
        siting: ChromaSiting,
    },
    /// Source planes do not describe a nonempty full coded image.
    SourceGeometry {
        plane: usize,
        actual: (usize, usize),
        expected: Option<(usize, usize)>,
    },
    /// Requested output rows/columns extend beyond the complete source image.
    OutputGeometry {
        origin: (usize, usize),
        extent: (usize, usize),
        source: (usize, usize),
    },
    /// Destination does not have the exact promised output descriptor.
    OutputDescriptor { actual: PixelDescriptor },
}

